"""Generated by OpenAI Codex on 2026-11-03. Authenticated map reads and editor-only writes."""

import copy
import json
import os
from typing import Annotated, Literal

from api.dependencies import db_session
from api.routers.auth.auth import enabled, require_user
from fastapi import APIRouter, Depends, HTTPException, Query, Request, Response
from pydantic import BaseModel, Field
from services.campus_map import (
    geometries,
    load_graph,
    normalize_links,
    persist,
    validate_graph,
)
from sqlalchemy import text

router = APIRouter(prefix="/api/map", tags=["Campus map"])
Identity = Annotated[dict, Depends(require_user)]


def can_edit(identity):
    allowed = {
        email.strip().casefold()
        for email in os.environ.get(
            "CATS_MAP_EDITOR_EMAILS", "tufts1cr@cmich.edu"
        ).split(",")
        if email.strip()
    }
    if not enabled():
        allowed.add("developer@example.test")
    return identity.get("email", "").casefold() in allowed


def require_editor(request: Request, identity: Identity):
    if not can_edit(identity):
        raise HTTPException(403, "Map editing is restricted to approved developers")
    # Production CSRF is checked by require_user; enforce Origin in development too.
    if not enabled() and request.method == "POST":
        allowed = set(
            os.environ.get(
                "CORS_ORIGINS", "http://localhost:8081,http://127.0.0.1:8081"
            ).split(",")
        )
        if request.headers.get("origin") not in allowed:
            raise HTTPException(403, "Request origin is not allowed")
    return identity


Editor = Annotated[dict, Depends(require_editor)]


@router.get("/permissions")
def permissions(identity: Identity, response: Response):
    response.headers["Cache-Control"] = "no-store"
    return {"can_edit": can_edit(identity)}


@router.get("/features")
def features(
    db: db_session,
    identity: Identity,
    bbox: str | None = None,
    q: str = "",
    kind: str = "",
    tag_key: str = "",
    tag_value: str = "",
    after: str = "",
    limit: Annotated[int, Query(ge=1, le=2000)] = 1000,
):
    clauses = [
        "f.geom IS NOT NULL",
        "(f.object_type <> 'node' OR f.tags <> '{}'::jsonb)",
        "f.id > :after",
    ]
    params = {"after": after, "limit": limit + 1}
    if bbox:
        try:
            west, south, east, north = [float(value) for value in bbox.split(",")]
            if not (-180 <= west <= east <= 180 and -90 <= south <= north <= 90):
                raise ValueError("Invalid bounds")
        except ValueError as exc:
            raise HTTPException(422, "bbox must be west,south,east,north") from exc
        clauses.append("f.geom && ST_MakeEnvelope(:west,:south,:east,:north,4326)")
        params.update(west=west, south=south, east=east, north=north)
    if q:
        clauses.append(
            "EXISTS (SELECT 1 FROM map_names n WHERE n.feature_id=f.id AND n.name ILIKE :q)"
        )
        params["q"] = "%" + q[:200] + "%"
    if tag_key:
        clauses.append("f.tags @> CAST(:tag AS jsonb)")
        params["tag"] = json.dumps({tag_key: tag_value})
    if kind == "building":
        clauses.append(
            "f.object_type <> 'node' AND f.tags ? 'building' AND f.tags->>'building' <> 'no'"
        )
    if kind == "entrance":
        clauses.append(
            "f.object_type = 'node' AND f.tags ? 'entrance' AND f.tags->>'entrance' <> 'no'"
        )
    rows = list(
        db.execute(
            text(
                "SELECT f.id,f.tags,f.building_id,f.link_status,f.geometry_status,f.version,ST_AsGeoJSON(f.geom)::json AS geometry FROM map_features f WHERE "
                + " AND ".join(clauses)
                + " ORDER BY f.id LIMIT :limit"
            ),
            params,
        ).mappings()
    )
    more = len(rows) > limit
    selected = rows[:limit]
    return {
        "type": "FeatureCollection",
        "features": [
            {
                "type": "Feature",
                "id": row["id"],
                "geometry": row["geometry"],
                "properties": {
                    **row["tags"],
                    "building_id": row["building_id"],
                    "link_status": row["link_status"],
                    "geometry_status": row["geometry_status"],
                    "version": row["version"],
                },
            }
            for row in selected
        ],
        "next": selected[-1]["id"] if more else None,
    }


@router.get("/features/{object_type}/{identifier}")
def detail(object_type: str, identifier: str, db: db_session, identity: Identity):
    key = f"{object_type}/{identifier}"
    row = (
        db.execute(
            text(
                "SELECT id,object_type,osm_id,tags,building_id,link_status,geometry_status,version,ST_AsGeoJSON(geom)::json AS geometry FROM map_features WHERE id=:id"
            ),
            {"id": key},
        )
        .mappings()
        .first()
    )
    if not row:
        raise HTTPException(404, "Feature not found")
    return dict(row)


@router.get("/editor")
def snapshot(db: db_session, identity: Editor, response: Response):
    response.headers["Cache-Control"] = "no-store"
    # One lock gives the revision and graph a consistent snapshot during concurrent saves.
    revision = db.execute(
        text("SELECT revision FROM map_dataset WHERE singleton FOR SHARE")
    ).scalar_one()
    objects = load_graph(db)
    return {"revision": revision, "objects": list(objects.values())}


class Ref(BaseModel):
    id: str = Field(max_length=100)
    type: Literal["node", "way", "relation"]
    role: str = Field(default="", max_length=255)


class FeatureInput(BaseModel):
    id: str = Field(max_length=100)
    type: Literal["node", "way", "relation"]
    tags: dict[str, str]
    refs: list[Ref] = Field(default_factory=list, max_length=20000)
    position: tuple[float, float] | None = None
    building_id: str | None = None


class ChangeSet(BaseModel):
    revision: int = Field(ge=1)
    upserts: list[FeatureInput] = Field(max_length=5000)
    deletes: list[str] = Field(max_length=5000)


@router.post("/editor")
def save(changes: ChangeSet, db: db_session, identity: Editor):
    revision = db.execute(
        text("SELECT revision FROM map_dataset WHERE singleton FOR UPDATE")
    ).scalar_one()
    if revision != changes.revision:
        raise HTTPException(
            409,
            "Map changed since you loaded it. Export your draft, then reload and reconcile.",
        )
    old = load_graph(db)
    objects = copy.deepcopy(old)
    ids = [obj.id for obj in changes.upserts]
    if len(set(ids)) != len(ids) or set(ids) & set(changes.deletes):
        raise HTTPException(422, "Duplicate or conflicting edit IDs")
    for key in changes.deletes:
        if key not in objects:
            raise HTTPException(404, "Deleted feature no longer exists")
        del objects[key]
    for value in changes.upserts:
        record = value.model_dump(mode="json")
        previous = old.get(value.id, {})
        objects[value.id] = {
            **previous,
            **record,
            "osm_id": previous.get("osm_id"),
            "source_tags": previous.get("source_tags", {}),
            "version": previous.get("version", 0),
            "link_status": previous.get("link_status", "not_applicable"),
        }
    for value in changes.upserts:
        if old.get(value.id, {}).get("building_id") and value.building_id is None:
            objects[value.id]["link_status"] = "unlinked_manual"
    try:
        validate_graph(objects, old)
        normalize_links(objects)
        geometry, status = geometries(objects)
        old_geometry, old_status = geometries(old)
    except (ValueError, KeyError, TypeError) as exc:
        raise HTTPException(422, str(exc)) from exc
    changed = set(changes.deletes)
    for key, obj in objects.items():
        if obj != old.get(key) or (
            geometry[key].wkb if geometry[key] is not None else None
        ) != (old_geometry[key].wkb if old_geometry.get(key) is not None else None):
            if status[key] in {"invalid", "incomplete"} and (
                key not in old or status[key] != old_status.get(key) or key in ids
            ):
                raise HTTPException(
                    422, f"Edit creates invalid or incomplete geometry: {key}"
                )
            obj["version"] = old.get(key, {}).get("version", 0) + 1
            changed.add(key)
    if not changed:
        return {"revision": revision, "changed": 0}
    persist(db, objects, geometry, status, changed)
    if changes.deletes:
        db.execute(
            text("DELETE FROM map_features WHERE id=ANY(:ids)"),
            {"ids": changes.deletes},
        )
    next_revision = revision + 1
    db.execute(
        text(
            "INSERT INTO map_changes(revision,actor_sub,actor_email,before_state,after_state) VALUES(:revision,:sub,:email,CAST(:before AS jsonb),CAST(:after AS jsonb))"
        ),
        {
            "revision": next_revision,
            "sub": identity["sub"],
            "email": identity["email"],
            "before": json.dumps({key: old.get(key) for key in changed}),
            "after": json.dumps({key: objects.get(key) for key in changed}),
        },
    )
    db.execute(
        text("UPDATE map_dataset SET revision=:revision WHERE singleton"),
        {"revision": next_revision},
    )
    db.commit()
    return {"revision": next_revision, "changed": len(changed)}
